-- Week 1 proposed PostgreSQL schema. Not deployed or runtime-tested.
-- UUID identifiers are generated by the application.
BEGIN;
CREATE TABLE users (
  id UUID PRIMARY KEY,
  name VARCHAR(80) NOT NULL CHECK (length(btrim(name)) > 0),
  email VARCHAR(254) NOT NULL UNIQUE CHECK (email = lower(btrim(email))),
  password_hash TEXT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE sessions (
  token_hash TEXT PRIMARY KEY,
  user_id UUID REFERENCES users(id) ON DELETE CASCADE,
  csrf_token TEXT NOT NULL,
  expires_at TIMESTAMPTZ NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  CHECK (expires_at > created_at)
);
-- Anonymous sessions support CSRF protection before authentication.
-- On successful login, rotate the token and set user_id.
CREATE INDEX sessions_expiry_idx ON sessions(expires_at);
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE TABLE projects (
  id UUID PRIMARY KEY,
  owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  name VARCHAR(100) NOT NULL CHECK (length(btrim(name)) > 0),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX projects_owner_idx ON projects(owner_id);
CREATE TABLE tasks (
  id UUID PRIMARY KEY,
  project_id UUID NOT NULL REFERENCES projects(id) ON DELETE CASCADE,
  title VARCHAR(160) NOT NULL CHECK (length(btrim(title)) > 0),
  description TEXT NOT NULL DEFAULT '' CHECK (length(description) <= 2000),
  status VARCHAR(20) NOT NULL DEFAULT 'todo'
    CHECK (status IN ('todo', 'in_progress', 'done')),
  priority VARCHAR(20) NOT NULL DEFAULT 'normal'
    CHECK (priority IN ('low', 'normal', 'high')),
  due_date DATE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX tasks_project_status_due_idx ON tasks(project_id, status, due_date);
-- Application updates updated_at on each successful project/task change.
-- Always enforce ownership using the authenticated session user, for example:
-- SELECT t.* FROM tasks t JOIN projects p ON p.id = t.project_id
-- WHERE t.id = $1 AND p.owner_id = $2;
COMMIT;
